"""Add the IR Source node of every demo layer to sources.json, generated by the Rust GeoParquet reader (not re-derived in Python).

The static site must give the canonical plan builder (`geo-plan`, run as WebAssembly in the page) exactly the Source node the gateway would build
with `open_source` from the same file: schema, CRS, statistics. `crates/geo-source-geoparquet/examples/ir_source.rs` prints it; this script stores it,
with the layer's logical uri `demo/<version>/<file>` (host independent: the manifest maps it to a URL), under `ir_source` in sources.json.

    python data/scripts/ir_sources.py [<pack dir containing sources.json, pack.json and <version>/>]      (default: data/public-demo)
"""

from __future__ import annotations

import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def ir_source_nodes(files: dict[str, Path]) -> dict[str, dict]:
    """`files`: layer id -> GeoParquet path. Returns layer id -> Source node (uri still the local path)."""
    paths = [str(p) for p in files.values()]
    out = subprocess.run(
        ["cargo", "run", "-q", "-p", "geo-source-geoparquet", "--example", "ir_source", "--", *paths],
        cwd=ROOT, capture_output=True, text=True, encoding="utf-8", check=True,
    ).stdout
    by_path = json.loads(out)
    return {sid: by_path[str(p)] for sid, p in files.items()}


def apply(pack: Path) -> None:
    manifest = json.loads((pack / "pack.json").read_text(encoding="utf-8"))
    sources = json.loads((pack / "sources.json").read_text(encoding="utf-8"))
    version = manifest["version"]
    files = {sid: (pack / f["path"]).resolve() for sid, f in manifest["files"].items()}
    nodes = ir_source_nodes(files)
    for s in sources["sources"]:
        node = nodes[s["id"]]
        node["uri"] = f"demo/{manifest['files'][s['id']]['path']}"  # the logical uri: host independent, the manifest maps it to a URL
        s["ir_source"] = node
    (pack / "sources.json").write_text(json.dumps(sources, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")
    print(f"ir_source added for {len(nodes)} layers ({version})")


if __name__ == "__main__":
    apply(Path(sys.argv[1]) if len(sys.argv) > 1 else ROOT / "data" / "public-demo")
